1	import * as THREE from "three";
2	import { BLOCK_COLORS, BlockId } from "./blocks";
3	import { doorState, isDoorBlock } from "./doors";
4	import { isDetectorRail, isPoweredRail, isRailBlock } from "./rails";
5	import { isRedstoneOn } from "./redstone";
6	import { isPartialBlock } from "./slabs";
7	
8	// Procedural texture atlas: one 16x16 tile per block face variant, painted on a
9	// canvas at startup. This is the only world module that touches the DOM.
10	export const ATLAS_TILE_SIZE = 16;
11	export const ATLAS_FACE_VARIANTS = 3; // top, side, bottom
12	export const ATLAS_COLUMNS = 16;
13	
14	// Tile range derived from the palette so new blocks get tiles automatically —
15	// a hardcoded last-block bound here once left new blocks sampling garbage UVs.
16	export const ATLAS_BLOCK_COUNT = Math.max(...Object.keys(BLOCK_COLORS).map(Number)) + 1;
17	export const ATLAS_ROWS = Math.ceil((ATLAS_BLOCK_COUNT * ATLAS_FACE_VARIANTS) / ATLAS_COLUMNS);
18	
19	let atlasTextureCache: THREE.CanvasTexture | null = null;
20	
21	function clamp01(v: number): number {
22	  return Math.max(0, Math.min(1, v));
23	}
24	
25	function tone(c: [number, number, number], mul: number, add = 0): [number, number, number] {
26	  return [clamp01(c[0] * mul + add), clamp01(c[1] * mul + add), clamp01(c[2] * mul + add)];
27	}
28	
29	function rgb(c: [number, number, number]): string {
30	  return `rgb(${Math.floor(clamp01(c[0]) * 255)}, ${Math.floor(clamp01(c[1]) * 255)}, ${Math.floor(clamp01(c[2]) * 255)})`;
31	}
32	
33	export function tileIndexFor(block: number, face: "top" | "side" | "bottom"): number {
34	  const faceId = face === "top" ? 0 : face === "side" ? 1 : 2;
35	  return block * ATLAS_FACE_VARIANTS + faceId;
36	}
37	
38	export function createBlockAtlasTexture(): THREE.CanvasTexture {
39	  if (atlasTextureCache) return atlasTextureCache;
40	
41	  const width = ATLAS_COLUMNS * ATLAS_TILE_SIZE;
42	  const height = ATLAS_ROWS * ATLAS_TILE_SIZE;
43	  const canvas = document.createElement("canvas");
44	  canvas.width = width;
45	  canvas.height = height;
46	  const ctx = canvas.getContext("2d");
47	  if (!ctx) throw new Error("Failed to create atlas context");
48	  ctx.imageSmoothingEnabled = false;
49	
50	  const drawTile = (block: number, face: "top" | "side" | "bottom") => {
51	    const tile = tileIndexFor(block, face);
52	    const col = tile % ATLAS_COLUMNS;
53	    const row = Math.floor(tile / ATLAS_COLUMNS);
54	    const ox = col * ATLAS_TILE_SIZE;
55	    const oy = row * ATLAS_TILE_SIZE;
56	
57	    const baseBlockColor = BLOCK_COLORS[block] ?? [1, 0, 1];
58	    let base = baseBlockColor;
59	    if (face === "top") base = tone(base, 1.08);
60	    if (face === "bottom") base = tone(base, 0.96);
61	    if (block === BlockId.Grass && face === "bottom") base = BLOCK_COLORS[BlockId.Dirt];
62	
63	    for (let y = 0; y < ATLAS_TILE_SIZE; y += 1) {
64	      for (let x = 0; x < ATLAS_TILE_SIZE; x += 1) {
65	        const h = Math.sin((x + block * 13 + (face === "top" ? 7 : face === "side" ? 17 : 29)) * 12.1 + (y + block * 19) * 7.7) * 43758.5453;
66	        const n = h - Math.floor(h);
67	        let c = tone(base, 0.92 + n * 0.22);
68	
69	        if (block === BlockId.Grass && face === "side" && y < 4) c = tone(BLOCK_COLORS[BlockId.Grass], 0.95 + n * 0.15);
70	        // Slabs/stairs inherit their material's accent so cut blocks read as
71	        // the same substance (plank grain / stone-cobble speckle).
72	        const stoneLike =
73	          block === BlockId.Stone ||
74	          block === BlockId.Cobblestone ||
75	          block === BlockId.Bedrock ||
76	          (isPartialBlock(block) && block !== BlockId.PlankSlab && !(block >= BlockId.PlankStairsNorth && block <= BlockId.PlankStairsWest));
77	        const plankLike =
78	          block === BlockId.Wood ||
79	          block === BlockId.Planks ||
80	          block === BlockId.PlankSlab ||
81	          (block >= BlockId.PlankStairsNorth && block <= BlockId.PlankStairsWest);
82	        if (stoneLike && n > 0.8) c = tone(base, 1.18);
83	        if (plankLike && (x + y) % 4 === 0) c = tone(base, 0.82);
84	        if (block === BlockId.CoalOre && n > 0.82) c = tone([0.09, 0.09, 0.11], 1);
85	        if (block === BlockId.SliverOre && n > 0.86) c = tone([0.93, 0.93, 0.95], 1);
86	        if (block === BlockId.RubyOre && n > 0.88) c = tone([0.86, 0.24, 0.24], 1);
87	        if (block === BlockId.GoldOre && n > 0.84) c = tone([0.96, 0.8, 0.25], 1);
88	        if (block === BlockId.SapphireOre && n > 0.86) c = tone([0.2, 0.62, 0.9], 1);
89	        if (block === BlockId.DiamondOre && n > 0.9) c = tone([0.7, 0.94, 0.98], 1);
90	        if (block === BlockId.Water) c = tone([0.22, 0.48, 0.85], 0.95 + n * 0.12, face === "top" ? 0.02 : 0);
91	        if (block === BlockId.Sand && n > 0.84) c = tone(base, 1.12);
92	        if (block === BlockId.Cactus && face === "side" && x % 4 === 0) c = tone(base, 0.72);
93	        if (block === BlockId.Snow) c = tone(base, 0.97 + n * 0.06);
94	        if (block === BlockId.Bed && face === "top" && y < 5) c = tone([0.95, 0.95, 0.97], 0.95 + n * 0.1); // pillow band
95	        if (block >= BlockId.WheatStage0 && block <= BlockId.WheatStage3 && face === "side" && x % 3 === 1) c = tone(base, 0.66); // gaps read as stalks
96	        if (block === BlockId.Sapling) {
97	          // A young sprout: a short brown stem in the lower center under a small
98	          // green leafy crown. Like wheat, it's a full cube painted to read as a plant.
99	          const stem = x >= 7 && x <= 8 && y >= 10;
100	          const crown = Math.abs(x - 7.5) + Math.abs(y - 6) < 5;
101	          c = stem ? tone([0.45, 0.32, 0.18], 0.85 + n * 0.2) : crown ? tone([0.27, 0.5, 0.2], 0.8 + n * 0.4) : tone([0.2, 0.36, 0.16], 0.85 + n * 0.25);
102	        }
103	        if (block === BlockId.Furnace && face === "side" && x >= 5 && x <= 10 && y >= 8 && y <= 12) c = tone([0.95, 0.45, 0.12], 0.85 + n * 0.3); // glowing mouth
104	        if (block === BlockId.Chest) {
105	          if ((x + y) % 4 === 0) c = tone(base, 0.82); // plank grain
106	          if (face === "top" && y === 8) c = tone(base, 0.6); // lid seam
107	          if (face === "side" && y === 7) c = tone(base, 0.58); // lid joint band
108	          if (face === "side" && x >= 7 && x <= 8 && y >= 6 && y <= 9) c = tone([0.62, 0.64, 0.68], 0.9 + n * 0.2); // metal latch
109	        }
110	        if (block === BlockId.MossyCobblestone) {
111	          if (n > 0.8) c = tone([0.5, 0.52, 0.5], 1.05); // pale cobble chunks
112	          if (n < 0.32) c = tone([0.2, 0.4, 0.16], 0.85 + n * 0.5); // moss patches in the cracks
113	        }
114	        if (block === BlockId.Spawner) {
115	          // A dark iron cage over a faint ember core — reads as a Minecraft spawner.
116	          const bar = x % 5 === 0 || y % 5 === 0;
117	          c = bar ? tone([0.32, 0.34, 0.4], 0.85 + n * 0.25) : tone([0.5, 0.16, 0.12], 0.5 + n * 0.6);
118	        }
119	        if (block === BlockId.Lava) {
120	          // Molten rock: a hot orange bed with brighter cracks and dark crust
121	          // flecks. The block emits max light, so it reads as glowing.
122	          const crack = n > 0.78;
123	          const crust = n < 0.2;
124	          c = crack ? tone([1, 0.78, 0.2], 1) : crust ? tone([0.35, 0.1, 0.04], 1) : tone([0.92, 0.34, 0.08], 0.85 + n * 0.4);
125	        }
126	        if (block === BlockId.Obsidian) {
127	          // Volcanic glass: a near-black bed with faint violet sheen bands and
128	          // the occasional bright fleck where the surface catches light.
129	          const sheen = (x + y * 2) % 7 === 0;
130	          c = sheen ? tone([0.24, 0.16, 0.4], 0.9 + n * 0.3) : tone([0.08, 0.06, 0.13], 0.85 + n * 0.35);
131	          if (n > 0.94) c = tone([0.55, 0.42, 0.78], 1); // light-catching fleck
132	        }
133	        if (block === BlockId.NetherPortal) {
134	          // A swirling violet surface: concentric sine bands around the tile
135	          // center over a deep purple bed, with bright sparks. Emits light 11,
136	          // so it reads as an active gateway.
137	          const cx = x - 7.5;
138	          const cy = y - 7.5;
139	          const ring = Math.sin(Math.sqrt(cx * cx + cy * cy) * 1.4 + n * 4);
140	          c = ring > 0.35 ? tone([0.62, 0.3, 0.9], 0.85 + n * 0.3) : tone([0.28, 0.1, 0.45], 0.8 + n * 0.3);
141	          if (n > 0.93) c = tone([0.9, 0.75, 1], 1); // spark
142	        }
143	        if (block === BlockId.Netherrack) {
144	          // Crimson pitted rock: darker pocks over the red base, a rare pale wart.
145	          if (n < 0.24) c = tone([0.3, 0.1, 0.09], 0.85 + n * 0.4);
146	          if (n > 0.92) c = tone([0.68, 0.4, 0.36], 1);
147	        }
148	        if (block === BlockId.Glowstone) {
149	          // A crystalline cluster: bright amber facets over a honey base, with
150	          // near-white glints along the facet joints (the block emits light 14).
151	          const facet = (x * 3 + y * 5) % 11 < 4;
152	          c = facet ? tone([1, 0.87, 0.5], 0.9 + n * 0.2) : tone([0.82, 0.6, 0.24], 0.85 + n * 0.3);
153	          if (n > 0.9) c = tone([1, 0.97, 0.85], 1);
154	        }
155	        if (block === BlockId.BlaziteOre) {
156	          // Netherrack base carrying ember-orange ore flecks that read as hot.
157	          if (n < 0.22) c = tone([0.3, 0.1, 0.09], 0.85 + n * 0.4);
158	          if (n > 0.8) c = tone([1, 0.55, 0.12], 0.9 + n * 0.25);
159	        }
160	        if (block === BlockId.Tnt) {
161	          // Classic TNT: a red block of "dynamite" with a white label band around
162	          // the sides and a darker cap on the top/bottom (the bundled fuse ends).
163	          if (face === "side") {
164	            c = y >= 6 && y <= 9 ? tone([0.92, 0.9, 0.86], 0.95 + n * 0.1) : tone([0.78, 0.2, 0.15], 0.88 + n * 0.2);
165	          } else {
166	            c = tone([0.5, 0.16, 0.12], 0.9 + n * 0.18);
167	            if ((x + y) % 5 === 0) c = tone([0.2, 0.18, 0.16], 1); // fuse-end flecks
168	          }
169	        }
170	        if (block === BlockId.Torch) {
171	          // A wooden stick on a dark ground with a bright flame near the top —
172	          // the block self-illuminates, so the flame reads as the light source.
173	          const onStick = x >= 7 && x <= 8 && y >= 6;
174	          const flame = x >= 6 && x <= 9 && y <= 6 && Math.abs(x - 7.5) + y * 0.5 < 4;
175	          if (face === "top")
176	            c = tone([1, 0.86, 0.32], 0.8 + n * 0.5); // looking down at the flame
177	          else if (flame) c = tone([1, 0.83, 0.3], 0.78 + n * 0.55);
178	          else if (onStick) c = tone([0.55, 0.38, 0.2], 0.85 + n * 0.2);
179	          else c = tone([0.05, 0.05, 0.07], 1);
180	        }
181	        if (block === BlockId.BrewingStand) {
182	          // A stone base under a glowing central rod, lit by a faint purple brew.
183	          const rod = x >= 7 && x <= 8;
184	          if (face === "top") {
185	            c = Math.abs(x - 7.5) + Math.abs(y - 7.5) < 3 ? tone([0.62, 0.42, 0.82], 0.9 + n * 0.3) : tone(base, 0.9 + n * 0.2);
186	          } else if (y >= 11) {
187	            c = tone([0.42, 0.43, 0.47], 0.9 + n * 0.2); // stone base
188	          } else if (rod && y >= 3) {
189	            c = tone([0.86, 0.8, 0.5], 0.85 + n * 0.3); // the glowing rod
190	          } else {
191	            c = tone([0.52, 0.46, 0.62], 0.85 + n * 0.25); // purple-tinted body
192	          }
193	        }
194	        if (block === BlockId.EnchantingTable) {
195	          // A dark obsidian plinth with a glowing arcane book floating on top.
196	          if (face === "top") {
197	            const onBook = Math.abs(x - 7.5) < 4 && Math.abs(y - 7.5) < 3;
198	            c = onBook ? tone([0.86, 0.3, 0.86], 0.85 + n * 0.4) : tone([0.12, 0.1, 0.2], 0.9 + n * 0.2);
199	          } else if (y <= 4) {
200	            c = tone([0.78, 0.32, 0.86], 0.8 + n * 0.5); // the glowing book band near the top
201	          } else {
202	            c = tone([0.14, 0.11, 0.24], 0.85 + n * 0.3); // obsidian base
203	            if (n > 0.85) c = tone([0.5, 0.4, 0.85], 1); // faint arcane sparkle
204	          }
205	        }
206	        if (block === BlockId.Anvil) {
207	          // A dark iron block: a lighter worktop on top and a polished face band near the top.
208	          if (face === "top") {
209	            c = tone([0.45, 0.46, 0.5], 0.9 + n * 0.2);
210	          } else if (y <= 3) {
211	            c = tone([0.5, 0.51, 0.55], 0.88 + n * 0.25); // the polished face band
212	          } else {
213	            c = tone([0.22, 0.23, 0.27], 0.85 + n * 0.3); // dark iron body
214	            if (n > 0.88) c = tone([0.4, 0.41, 0.45], 1); // faint metal fleck
215	          }
216	        }
217	        if (block === BlockId.Grindstone) {
218	          // A round stone wheel set in a wooden frame.
219	          if (face === "top") {
220	            const onWheel = Math.abs(x - 7.5) + Math.abs(y - 7.5) < 5;
221	            c = onWheel ? tone([0.55, 0.56, 0.58], 0.88 + n * 0.25) : tone([0.5, 0.36, 0.2], 0.9 + n * 0.2);
222	          } else if (y >= 5 && y <= 10) {
223	            c = tone([0.55, 0.56, 0.58], 0.85 + n * 0.3); // the stone wheel band
224	          } else {
225	            c = tone([0.5, 0.36, 0.2], 0.88 + n * 0.2); // wooden frame
226	          }
227	        }
228	        if (block === BlockId.Kelp) {
229	          // A swaying sea plant: a dark central stalk with paler fronds fanning
230	          // out to the sides. Like wheat, a full cube painted to read as a plant.
231	          const stalk = x >= 7 && x <= 8;
232	          const frond = (x + y * 2) % 5 === 0 || (ATLAS_TILE_SIZE - 1 - x + y * 2) % 5 === 0;
233	          c = stalk ? tone([0.13, 0.34, 0.2], 0.85 + n * 0.25) : frond ? tone([0.3, 0.58, 0.32], 0.8 + n * 0.35) : tone([0.1, 0.26, 0.18], 0.85 + n * 0.25);
234	        }
235	        if (block === BlockId.CoralPink || block === BlockId.CoralBlue) {
236	          // Reef coral: bright branching arms over a darker base, with pale polyp
237	          // flecks where the hash noise peaks.
238	          const branch = (x * 3 + y * 5 + block * 7) % 9 < 3;
239	          c = branch ? tone(base, 1.1 + n * 0.15) : tone(base, 0.6 + n * 0.2);
240	          if (n > 0.88) c = tone([0.95, 0.93, 0.88], 0.95);
241	        }
242	        if (isDoorBlock(block)) {
243	          const state = doorState(block)!;
244	          const panelY = state.upper ? y : y + ATLAS_TILE_SIZE;
245	          const border = x < 2 || x > 13 || panelY < 2 || panelY > 29;
246	          const inset = x >= 4 && x <= 11 && ((panelY >= 4 && panelY <= 13) || (panelY >= 18 && panelY <= 27));
247	          if (border) c = tone(base, 0.62);
248	          else if (inset) c = tone(base, 0.78 + n * 0.08);
249	          else c = tone(base, 0.95 + n * 0.12);
250	          if (!state.upper && x >= 11 && x <= 12 && y >= 5 && y <= 6) c = tone([0.82, 0.72, 0.36], 0.9 + n * 0.15);
251	        }
252	        if (block === BlockId.RedstoneWire || block === BlockId.RedstoneWireOn) {
253	          // A dust trail crossing the tile on a dark bed; the on variant reads
254	          // bright signal-red. The mesh is a flat overlay, so the top face is
255	          // what players mostly see.
256	          const lit = block === BlockId.RedstoneWireOn;
257	          const onTrail = (x >= 6 && x <= 9) || (y >= 6 && y <= 9);
258	          if (onTrail) c = lit ? tone([0.95, 0.22, 0.12], 0.82 + n * 0.35) : tone([0.45, 0.12, 0.08], 0.85 + n * 0.25);
259	          else c = tone([0.16, 0.14, 0.13], 0.9 + n * 0.15);
260	        }
261	        if (block === BlockId.Lever || block === BlockId.LeverOn) {
262	          // A cobblestone base with a wooden handle; the on state tips the
263	          // handle to the other side and lights a red fleck on the base top.
264	          const on = block === BlockId.LeverOn;
265	          const handleX = on ? 10 : 5;
266	          const onHandle = Math.abs(x - handleX) <= 1 && y >= 3 && y <= 11;
267	          if (face === "top") {
268	            c = tone([0.45, 0.46, 0.48], 0.85 + n * 0.25);
269	            if (on && Math.abs(x - 7.5) + Math.abs(y - 7.5) < 3) c = tone([0.9, 0.25, 0.15], 0.9 + n * 0.2);
270	          } else if (y >= 12) c = tone([0.45, 0.46, 0.48], 0.85 + n * 0.25);
271	          else if (onHandle) c = tone([0.55, 0.38, 0.2], 0.85 + n * 0.2);
272	          else c = tone([0.1, 0.1, 0.12], 1);
273	        }
274	        if (block === BlockId.RedstoneButton || block === BlockId.RedstoneButtonOn) {
275	          // A small stone pad with a beveled rim; pressed reads darker (and
276	          // the pressed mesh sits lower).
277	          const pressed = block === BlockId.RedstoneButtonOn;
278	          c = tone([0.5, 0.52, 0.54], (pressed ? 0.72 : 0.9) + n * 0.18);
279	          if (x < 1 || x > 14 || y < 1 || y > 14) c = tone([0.3, 0.31, 0.33], 0.9 + n * 0.1);
280	        }
281	        if (block === BlockId.PressurePlate || block === BlockId.PressurePlateOn) {
282	          // A plank pad with grain and a beveled rim; pressed reads darker.
283	          const pressed = block === BlockId.PressurePlateOn;
284	          c = tone([0.7, 0.56, 0.35], (pressed ? 0.75 : 0.92) + n * 0.15);
285	          if ((x + y) % 4 === 0) c = tone([0.6, 0.47, 0.29], pressed ? 0.75 : 0.9);
286	          if (x < 2 || x > 13 || y < 2 || y > 13) c = tone([0.5, 0.4, 0.25], 0.85 + n * 0.1);
287	        }
288	        if (block === BlockId.RedstoneTorchOff || block === BlockId.RedstoneTorch) {
289	          // The torch motif with a redstone tip: bright red when lit, a dead
290	          // crimson knob when its support is powered (the inverter's off state).
291	          const lit = block === BlockId.RedstoneTorch;
292	          const onStick = x >= 7 && x <= 8 && y >= 6;
293	          const tip = x >= 6 && x <= 9 && y <= 6 && Math.abs(x - 7.5) + y * 0.5 < 4;
294	          if (face === "top") c = lit ? tone([1, 0.35, 0.2], 0.8 + n * 0.5) : tone([0.3, 0.1, 0.08], 0.9 + n * 0.2);
295	          else if (tip) c = lit ? tone([0.95, 0.28, 0.15], 0.78 + n * 0.5) : tone([0.28, 0.09, 0.07], 0.9 + n * 0.2);
296	          else if (onStick) c = tone([0.55, 0.38, 0.2], 0.85 + n * 0.2);
297	          else c = tone([0.05, 0.05, 0.07], 1);
298	        }
299	        if (block === BlockId.RedstoneLamp || block === BlockId.RedstoneLampOn) {
300	          // A glowstone-style lattice: a dark frame over an ochre core that
301	          // brightens to a saturated glow when powered — the emitted block
302	          // light (emission 15) does the rest of the glowing.
303	          const lit = block === BlockId.RedstoneLampOn;
304	          const frame = x % 5 === 0 || y % 5 === 0;
305	          if (frame) c = tone([0.25, 0.2, 0.14], 0.9 + n * 0.2);
306	          else c = lit ? tone([1, 0.85, 0.42], 0.85 + n * 0.3) : tone([0.5, 0.4, 0.22], 0.85 + n * 0.25);
307	        }
308	        if (isRailBlock(block)) {
309	          // Two steel strips over wooden ties on a gravel bed. The strips run
310	          // along the tile's v axis; the mesher rotates the top face 90° for
311	          // north-south track. Powered rails carry a center power lane that
312	          // glows when on; detector rails a center sensor plate.
313	          const lit = isRedstoneOn(block);
314	          const strip = x === 3 || x === 4 || x === 11 || x === 12;
315	          const tie = y % 5 === 2 || y % 5 === 3;
316	          if (strip) {
317	            c = isPoweredRail(block) && lit ? tone([0.95, 0.62, 0.28], 0.88 + n * 0.22) : tone([0.62, 0.64, 0.68], 0.85 + n * 0.25);
318	          } else if (isDetectorRail(block) && x >= 6 && x <= 9 && y >= 6 && y <= 9) {
319	            c = lit ? tone([0.92, 0.3, 0.18], 0.88 + n * 0.22) : tone([0.55, 0.57, 0.6], 0.85 + n * 0.2);
320	          } else if (isPoweredRail(block) && (x === 7 || x === 8)) {
321	            c = lit ? tone([0.95, 0.35, 0.15], 0.85 + n * 0.3) : tone([0.4, 0.14, 0.1], 0.85 + n * 0.2);
322	          } else if (tie) {
323	            c = tone([0.45, 0.32, 0.18], 0.85 + n * 0.2);
324	          } else {
325	            c = tone([0.24, 0.2, 0.16], 0.9 + n * 0.15);
326	          }
327	        }
328	
329	        ctx.fillStyle = rgb(c);
330	        ctx.fillRect(ox + x, oy + y, 1, 1);
331	      }
332	    }
333	  };
334	
335	  for (let block = BlockId.Grass; block < ATLAS_BLOCK_COUNT; block += 1) {
336	    drawTile(block, "top");
337	    drawTile(block, "side");
338	    drawTile(block, "bottom");
339	  }
340	
341	  const texture = new THREE.CanvasTexture(canvas);
342	  texture.magFilter = THREE.NearestFilter;
343	  texture.minFilter = THREE.NearestMipmapNearestFilter;
344	  texture.wrapS = THREE.ClampToEdgeWrapping;
345	  texture.wrapT = THREE.ClampToEdgeWrapping;
346	  texture.flipY = false;
