    expect(canMineBlock(BlockId.Netherrack, 1)).toBe(true);
    expect(canMineBlock(BlockId.BlaziteOre, 6)).toBe(false);
    expect(canMineBlock(BlockId.BlaziteOre, 7)).toBe(true);
  });
});

